    Experiment with a different texture on each side of the cube and 
    how to sort which side based on the normal vector of the SDF box. 
    Still some tweaking and mucking about. I'd like to do something 
    interesting with the transitions.

    ⭐ first shader of 2025
    Box Test - Time and Space
    01/12/2025  @byt3_m3chanic 

*/

#define R iResolution
#define M iMouse
#define T iTime

#define PI  3.1415926
#define PI2 6.2831853

#define MIN_DIST 1e-3
#define MAX_DIST 40.

#define eoc(t) (t=t-1.)*t*t+1.
#define eic(t) t*t*t


vec3 hit,hp;
mat2 mx,my,nx,ny,mz,mw,nz,nw;

mat2 rot (float a) { return mat2(cos(a),sin(a),-sin(a),cos(a)); }
float hash21( vec2 p ) { return fract(sin(dot(p,vec2(23.43,35.23))) *472.323); }

// timing functions
float lerp (float b, float e, float t) { return clamp((t - b) / (e - b), 0., 1.); }

float box(vec3 p, vec3 b){
    vec3 d = abs(p)-b;
    return length(max(d,0.))+min(max(d.x,max(d.y,d.z)),.0);
}

//globals
vec3 s_hit, g_hit;
vec2 s_id, g_id;
float tspeed=0., tmod=0., t1=0., t3=0., t4=0.;

//scales for all things
const float scale = .75;
const float scale_h = scale/2.;
const vec2 s = vec2(scale*2.2);

const vec2 pos = vec2(.5,-.5);
const vec2[4] ps4 = vec2[4](pos.yx,pos.xx,pos.xy,pos.yy);

float pattern(inout vec3 q, vec2 id) {
    float res = 1e5;
    float rnd = hash21(id);

    float ths = (rnd*1.37)+fract(rnd*4324.35);

    // turn based on mod time
    ths += rnd;
    float t1 = lerp(ths    ,ths+  .5,tmod);
    float t2 = lerp(ths+5. ,ths+ 5.5,tmod);
    float t3 = lerp(ths+10.,ths+10.5,tmod);
    float t4 = lerp(ths+15.,ths+15.5,tmod);  
    t1 = eoc(t1); t1 = eic(t1);
    t2 = eoc(t2); t2 = eic(t2);
    t3 = eoc(t3); t3 = eic(t3);
    t4 = eoc(t4); t4 = eic(t4);

    vec3 nq = q-vec3(0,((t2-t3)+(t1-t4))*scale,0);

    // messy first draft
    float rf = 1.5707;

    nx = rot(rf*(t1-t2));
    ny = rot(rf*(t3+t4));
    nq.zy *= nx;
    nq.xz *= ny;

    nz = rot(rf*(t1-t4));
    nw = rot(rf*(t2-t3));
    nq.zy *= nz;
    nq.xz *= nw;

    float d = box(nq,vec3(scale_h))-.0185;
    if(d<res) {
        res = d;
        q = nq;
    }
    return res;
}
// block map -v4 tap technique from @Shane
vec2 map(vec3 q3){
    vec2 res = vec2(1e5,0.), p, ip, ct = vec2(0);
    float t=1e5, y=1e5, m=1.;
    for(int i =0; i<4; i++){

        ct = ps4[i]/2. -  ps4[0]/2.;
        p = q3.xz - ct*s;
        ip = floor(p/s) + .5;
        p -= (ip)*s;
        vec2 idi = (ip + ct)*s;
        idi=abs(idi+30.);
        vec3 q = vec3(p.x,q3.y,p.y);
        float b = pattern(q,idi);

        if(b<t ) { 
            t = b;
            s_id = idi, s_hit = q;
            mx=nx, my=ny, mz=nz, mw=nw;
        }
    }

	if(t<res.x) res = vec2(t,1.);
    return res;
}

vec3 normal(vec3 p, float t) {
    float e = MIN_DIST*t;
    vec2 h =vec2(1,-1)*.5773;
    vec3 n = h.xyy * map(p+h.xyy*e).x+
             h.yyx * map(p+h.yyx*e).x+
             h.yxy * map(p+h.yxy*e).x+
             h.xxx * map(p+h.xxx*e).x;
    return normalize(n);
}

vec3 hsv(vec3 c) {
    vec3 rgb = clamp(abs(mod((c.x+T*.03)*6.+vec3(0,4,2),6.)-3.)-1.,0.,1.);
    return c.z * mix(vec3(1),rgb,c.y);
}

float tiles(vec2 uv,vec2 id, float thickness) {
    vec2 q = uv;
    float rnd = hash21(id.xy);
    if(rnd>.5) q.y = -q.y;
    vec2 q2 = length(q-scale_h)<length(q+scale_h) ? q-scale_h : q+scale_h;
    float d1 = abs(length(q2)-scale_h)-thickness;
    if(fract(rnd*32.27)>.85) d1 = min(length(q.x)-thickness,length(q.y)-thickness);
    return d1;
}
float movement;
vec4 FC = vec4(.22,.24,.29,0);
vec4 render(inout vec3 ro, inout vec3 rd, inout vec3 ref, bool last, inout float d) {

    vec3 C = vec3(0), p = ro;
    float m = 0.;

    for(int i=0;i<100;i++) {
        p = ro + rd * d;
        vec2 ray = map(p);
        if(ray.x<MIN_DIST*d||d>MAX_DIST)break;
        d += i<25? ray.x*.25: ray.x;
        m  = ray.y;
    } 
    hp = s_hit;
    g_id = s_id;
    float alpha = 0.;
    if(d<MAX_DIST)
    {
        vec3 n = normal(p,d);
        vec3 lpos =  vec3(-5.+movement,12,-5);
        vec3 l = normalize(lpos-p);
        float diff = clamp(dot(n,l),.001,1.);

        int face;
        vec3 cuv = s_hit, clr;
        if(m>0.) {
            // quick find the correct face with normal
            vec3 tn = n;
            tn.zy *= mx;
            tn.xz *= my; 
            tn.zy *= mz;
            tn.xz *= mw; 
            vec3 aN = abs(tn);
            ivec3 idF = ivec3(tn.x<-.25? 0 : 5, tn.y<-.25? 1 : 4, tn.z<-.25? 2 : 3);
            face = aN.x>.5? idF.x : aN.y>.5? idF.y : idF.z;

            if(face==0||face==5) { cuv = s_hit.yzx; clr=vec3(.075); }
            if(face==1) { cuv = s_hit.zxy; clr=hsv(vec3(hash21(g_id+float(face*5))*.45,.95,.35)); }
            if(face==4) { cuv = s_hit.zxy; clr=hsv(vec3(.085+.085*(g_id.x*.3),.75,.45)); }
            if(face==2||face==3) { cuv = s_hit.xyz; clr=vec3(.75); }

        }

        float shdw = 1.;
        for( float t = .05; t < 12.; ) {
            float h = map(p + l*t).x;
            if( h<MIN_DIST ) { shdw = 0.; break; }
            shdw = min(shdw, 18.*h/t);
            t += h;
            if( shdw<MIN_DIST || t>32. ) break;
        }
        diff = mix(diff,diff*shdw,.75);

        float tx = .10275;

        vec3 h = clr;
        vec2 uv = cuv.xy;

        if (face==2||face==3) tx = .1+.07*sin(p.x*.85+T*.1);

        float d1 = tiles(uv,g_id+float(face),tx);
        float d2 = d1;
        float px = fwidth(uv.x);
        vec3 clx = face == 1 ? vec3(.7):vec3(.075);

        if(face==1) {
            float d = .5+2.5*sin((uv.x-uv.y)*54.);
            h = mix(h,clamp(h+.1,h,vec3(1)),smoothstep(px,-px,d));
        }
        if(face==0||face==5){ 
            d1 = abs(d1)-.02;
            clx = vec3(.01);
            h = mix(h,hsv(vec3((2.5-hash21(g_id.yx))*.2,1.,.3)),smoothstep(px,-px,d2+.075));
        }
        if(face==2||face==3){
            uv *= rot(.78);
            float d = length(fract(uv*12.)-.5)-.4;
            h = mix(h,clamp(h-.3,vec3(.001),h),smoothstep(px,-px,d));
            h = mix(h,vec3(.7),smoothstep(px,-px,d1-.05));
            clx = hsv(vec3((1.-hash21(g_id.yx))*.25,.95,.45));
            d1 = min(abs(d1)-.01,d2+.05);
        }
        if(face==4) {
            vec2 vv = fract(uv*12.)-.5;
            vv *= rot(.78);
            float d = abs(min(length(vv.x),length(vv.y)))-.075;
            h = mix(h,clamp(h+.05,h,vec3(1)),smoothstep(px,-px,d));
        }
        h = mix(h,clx,smoothstep(px,-px,d1));

        ref = mix(h*.5,h*.1,smoothstep(-px,px,d1));

        C = h * diff;
        C = mix(FC.rgb,C, exp(-.0001*d*d*d));

        ro = p+n*.01;
        rd = reflect(rd,n);

    }else{
        C = FC.rgb;
    } 
    return vec4(C,alpha);
}
float zoom = 4.75;
void mainImage( out vec4 O, in vec2 F )
{ 

    tspeed = T*.8;
    movement = T*-.45;
    tmod = mod(tspeed,20.);

    vec2 uv = (2.*F.xy-R.xy)/max(R.x,R.y);
    vec3 ro = vec3(uv*zoom,-(zoom+5.));
    vec3 rd = vec3(0,0,1);

    mat2 rx =rot(.58);
    mat2 ry =rot(-.72);

    ro.zy*=rx;rd.zy*=rx;
    ro.xz*=ry;rd.xz*=ry;
    ro.x += movement;

    vec3 C = vec3(0),ref=vec3(0),fil=vec3(1);
    float d = 0.,a = 0., numBounces = 2.;

    for(float i=0.; i<numBounces; i++) {
        d =0.;
        vec4 pass = render(ro, rd, ref, i==numBounces-1., d);
        C += pass.rgb*fil;
        fil*=ref;
        if(i==0.) a = d;
    }

    O = vec4(pow(C, vec3(.4545)),1.0);
}
